  async listContacts(o) {
    await tick();
    return applyList(store.contacts, o, ["full_name", "email_id", "company_name", "mobile_no"]);
  },

  async listToDos(o) {
    await tick();
    return applyList(store.todos, o, ["description", "reference_name"]);
  },
  async setToDoStatus(n, status) {
    const t = store.todos.find((x) => x.name === n);
    if (!t) throw new Error("Aufgabe nicht gefunden");
    t.status = status;
    t.modified = new Date().toISOString();
  },
};

export const LEAD_STATUS_LABEL: Record<string, string> = {
  Lead: "Neu",
  Open: "Offen",
  Replied: "Beantwortet",
  Opportunity: "Chance",
  Quotation: "Angebot",
  Interested: "Interessiert",
  Converted: "Konvertiert",
  "Do Not Contact": "Nicht kontaktieren",
  Lost: "Verloren",
  Closed: "Geschlossen",
  Cancelled: "Abgebrochen",
};

export const STAGE_LABEL: Record<string, string> = {
  Prospecting: "Akquise",
  Qualification: "Qualifizierung",
  "Needs Analysis": "Bedarfsanalyse",
  "Proposal/Price Quote": "Angebot",
  "Negotiation/Review": "Verhandlung",
};

export const PRIORITY_LABEL: Record<string, string> = { Low: "Niedrig", Medium: "Mittel", High: "Hoch" };

export type Tone = "gray" | "blue" | "green" | "amber" | "red" | "violet";

export const STATUS_TONE: Record<string, Tone> = {
  Lead: "gray",
  Open: "blue",
  Replied: "violet",
  Opportunity: "amber",
  Quotation: "amber",
  Interested: "green",
  Converted: "green",
  "Do Not Contact": "red",
  Lost: "red",
  Closed: "gray",
  Cancelled: "gray",
  High: "red",
  Medium: "amber",
  Low: "gray",
};

export function money(amount: number, currency = "EUR") {
  return new Intl.NumberFormat("de-DE", { style: "currency", currency, maximumFractionDigits: 0 }).format(amount);
}

export function date(iso?: string) {
  if (!iso) return "–";
  return new Intl.DateTimeFormat("de-DE", { dateStyle: "medium" }).format(new Date(iso));
}

export function relative(iso: string) {
  const diff = (new Date(iso).getTime() - Date.now()) / 1000;
  const rtf = new Intl.RelativeTimeFormat("de-DE", { numeric: "auto" });
  const abs = Math.abs(diff);
  if (abs < 3600) return rtf.format(Math.round(diff / 60), "minute");
  if (abs < 86_400) return rtf.format(Math.round(diff / 3600), "hour");
  if (abs < 86_400 * 30) return rtf.format(Math.round(diff / 86_400), "day");
  return rtf.format(Math.round(diff / (86_400 * 30)), "month");
}

export function initials(name: string) {
  return name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((p) => p[0]?.toUpperCase())
    .join("");
}

"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { db } from "@/lib/data";
import { LEAD_STATUSES, OPPORTUNITY_STAGES, type LeadStatus } from "@/lib/types";

// Serverseitige Prüfungen – das Formular im Browser wird nicht vertraut.

export type FormState = { error?: string };

export async function createLeadAction(_prev: FormState, form: FormData): Promise<FormState> {
  const first_name = String(form.get("first_name") ?? "").trim();
  const last_name = String(form.get("last_name") ?? "").trim();
  const email_id = String(form.get("email_id") ?? "").trim();
  const status = String(form.get("status") ?? "Lead") as LeadStatus;

  if (!first_name) return { error: "Vorname ist ein Pflichtfeld." };
  if (email_id && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email_id)) return { error: "E-Mail-Adresse ist ungültig." };
  if (!LEAD_STATUSES.includes(status)) return { error: "Ungültiger Status." };

  const lead = await db().createLead({
    first_name,
    last_name: last_name || undefined,
    company_name: String(form.get("company_name") ?? "").trim() || undefined,
    email_id: email_id || undefined,
    mobile_no: String(form.get("mobile_no") ?? "").trim() || undefined,
    source: String(form.get("source") ?? "").trim() || undefined,
    status,
  });
  revalidatePath("/leads");
  redirect(`/leads/${encodeURIComponent(lead.name)}`);
}

export async function setLeadStatusAction(name: string, status: string) {
  if (!LEAD_STATUSES.includes(status as LeadStatus)) throw new Error("Ungültiger Status");
  await db().setLeadStatus(name, status as LeadStatus);
  revalidatePath("/leads");
  revalidatePath(`/leads/${encodeURIComponent(name)}`);
}

export async function setOpportunityStageAction(name: string, stage: string) {
  if (!(OPPORTUNITY_STAGES as readonly string[]).includes(stage)) throw new Error("Ungültige Phase");
  await db().setOpportunityStage(name, stage);
  revalidatePath("/opportunities");
  revalidatePath("/");
}

export async function toggleToDoAction(name: string, done: boolean) {
  await db().setToDoStatus(name, done ? "Closed" : "Open");
  revalidatePath("/todos");
  revalidatePath("/");
}

