"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { Building2, CheckSquare, Contact, Handshake, LayoutDashboard, Users } from "lucide-react";

const NAV = [
  { href: "/", label: "Übersicht", icon: LayoutDashboard },
  { href: "/leads", label: "Leads", icon: Users },
  { href: "/opportunities", label: "Chancen", icon: Handshake },
  { href: "/customers", label: "Kunden", icon: Building2 },
  { href: "/contacts", label: "Kontakte", icon: Contact },
  { href: "/todos", label: "Aufgaben", icon: CheckSquare },
];

export function Sidebar({ source }: { source: "mock" | "erpnext" }) {
  const pathname = usePathname();

  return (
    <aside className="flex w-56 shrink-0 flex-col border-r border-gray-200 bg-gray-50">
      <div className="flex h-12 items-center gap-2 px-4">
        <div className="flex size-6 items-center justify-center rounded-md bg-gray-900 text-xs font-semibold text-white">C</div>
        <span className="font-semibold text-gray-900">CRM</span>
      </div>
      <nav className="flex flex-col gap-0.5 px-2 py-2">
        {NAV.map(({ href, label, icon: Icon }) => {
          const active = href === "/" ? pathname === "/" : pathname.startsWith(href);
          return (
            <Link
              key={href}
              href={href}
              className={`flex items-center gap-2.5 rounded-md px-2.5 py-1.5 ${
                active ? "bg-white font-medium text-gray-900 shadow-sm ring-1 ring-gray-200" : "text-gray-600 hover:bg-gray-100 hover:text-gray-900"
              }`}
            >
              <Icon className="size-4" strokeWidth={1.75} />
              {label}
            </Link>
          );
        })}
      </nav>
      <div className="mt-auto p-3">
        <div
          className={`rounded-md px-2.5 py-2 text-xs ${
            source === "mock" ? "bg-amber-50 text-amber-800 ring-1 ring-amber-200" : "bg-green-50 text-green-800 ring-1 ring-green-200"
          }`}
        >
          {source === "mock" ? "Demo-Modus: Beispieldaten" : "Verbunden mit ERPNext"}
        </div>
      </div>
    </aside>
  );
}

import Link from "next/link";
import type { ReactNode } from "react";
import { initials, STATUS_TONE, type Tone } from "@/lib/format";

const TONES: Record<Tone, string> = {
  gray: "bg-gray-100 text-gray-700",
  blue: "bg-blue-50 text-blue-700",
  green: "bg-green-50 text-green-700",
  amber: "bg-amber-50 text-amber-800",
  red: "bg-red-50 text-red-700",
  violet: "bg-violet-50 text-violet-700",
};

export function Badge({ value, label, tone }: { value: string; label?: string; tone?: Tone }) {
  const t = tone ?? STATUS_TONE[value] ?? "gray";
  return (
    <span className={`inline-flex items-center gap-1.5 rounded-full px-2 py-0.5 text-xs font-medium ${TONES[t]}`}>
      <span className="size-1.5 rounded-full bg-current opacity-70" />
      {label ?? value}
    </span>
  );
}

export function Avatar({ name, size = "sm" }: { name: string; size?: "sm" | "lg" }) {
  return (
    <span
      className={`inline-flex shrink-0 items-center justify-center rounded-full bg-gray-200 font-medium text-gray-700 ${
        size === "lg" ? "size-12 text-base" : "size-6 text-[10px]"
      }`}
    >
      {initials(name)}
    </span>
  );
}

export function PageHeader({ title, crumbs, actions }: { title: string; crumbs?: { href: string; label: string }[]; actions?: ReactNode }) {
  return (
    <header className="flex h-12 shrink-0 items-center justify-between border-b border-gray-200 px-5">
      <div className="flex items-center gap-1.5 text-gray-500">
        {crumbs?.map((c) => (
          <span key={c.href} className="flex items-center gap-1.5">
            <Link href={c.href} className="hover:text-gray-900">
              {c.label}
            </Link>
            <span>/</span>
          </span>
        ))}
        <h1 className="font-medium text-gray-900">{title}</h1>
      </div>
      <div className="flex items-center gap-2">{actions}</div>
    </header>
  );
}

export function ButtonLink({ href, children }: { href: string; children: ReactNode }) {
  return (
    <Link href={href} className="inline-flex h-8 items-center gap-1.5 rounded-md bg-gray-900 px-3 text-sm font-medium text-white hover:bg-gray-800">
      {children}
    </Link>
  );
}

export function Empty({ children }: { children: ReactNode }) {
  return <div className="px-5 py-16 text-center text-gray-500">{children}</div>;
}

export function Field({ label, children }: { label: string; children: ReactNode }) {
  return (
    <div className="grid grid-cols-[140px_1fr] items-start gap-3 py-1.5">
      <dt className="text-gray-500">{label}</dt>
      <dd className="min-w-0 break-words text-gray-900">{children ?? "–"}</dd>
    </div>
  );
}

export function Table({ head, children }: { head: string[]; children: ReactNode }) {
  return (
    <div className="overflow-x-auto">
      <table className="w-full text-left">
        <thead>
          <tr className="border-b border-gray-200 text-xs text-gray-500">
            {head.map((h) => (
              <th key={h} className="whitespace-nowrap px-5 py-2 font-medium">
                {h}
              </th>
            ))}
          </tr>
        </thead>
        <tbody className="divide-y divide-gray-100">{children}</tbody>
      </table>
    </div>
  );
}

"use client";

import { usePathname, useRouter, useSearchParams } from "next/navigation";
import { Search } from "lucide-react";
import { useEffect, useState, useTransition } from "react";

// Suche und Statusfilter landen in der URL (?q=…&status=…), damit Listen teilbar sind.
export function ListToolbar({ statuses, labels, count }: { statuses?: readonly string[]; labels?: Record<string, string>; count: number }) {
  const router = useRouter();
  const pathname = usePathname();
  const params = useSearchParams();
  const [q, setQ] = useState(params.get("q") ?? "");
  const [pending, start] = useTransition();

  function push(next: Record<string, string>) {
    const sp = new URLSearchParams(params.toString());
    for (const [k, v] of Object.entries(next)) {
      if (v) sp.set(k, v);
      else sp.delete(k);
    }
    start(() => router.replace(`${pathname}?${sp}`));
  }

  useEffect(() => {
    if (q === (params.get("q") ?? "")) return;
    const t = setTimeout(() => push({ q }), 250);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [q]);

  return (
    <div className="flex items-center gap-2 border-b border-gray-200 px-5 py-2.5">
      <label className="relative">
        <Search className="pointer-events-none absolute left-2.5 top-1/2 size-3.5 -translate-y-1/2 text-gray-400" />
        <input
          value={q}
          onChange={(e) => setQ(e.target.value)}
          placeholder="Suchen…"
          className="h-8 w-64 rounded-md bg-gray-100 pl-8 pr-3 outline-none placeholder:text-gray-400 focus:bg-white focus:ring-1 focus:ring-gray-300"
        />
      </label>
      {statuses && (
        <select
          value={params.get("status") ?? ""}
          onChange={(e) => push({ status: e.target.value })}
          className="h-8 rounded-md bg-gray-100 px-2 outline-none focus:ring-1 focus:ring-gray-300"
        >
          <option value="">Alle Status</option>
          {statuses.map((s) => (
            <option key={s} value={s}>
              {labels?.[s] ?? s}
            </option>
          ))}
        </select>
      )}
      <span className={`ml-auto text-xs text-gray-500 ${pending ? "opacity-50" : ""}`}>{count} Einträge</span>
    </div>
  );
}

import { Sidebar } from "@/components/Sidebar";
import { db } from "@/lib/data";

export default function CrmLayout({ children }: LayoutProps<"/">) {
  return (
    <div className="flex h-full">
      <Sidebar source={db().kind} />
      <main className="flex min-w-0 flex-1 flex-col overflow-y-auto">{children}</main>
    </div>
  );
}

