async convertLead(n) {
  await tick();
  const l = store.leads.find((x) => x.name === n);
  if (!l) throw new Error("Lead nicht gefunden");
  const customerName = l.company_name || l.lead_name;
  let customer = store.customers.find((c) => c.name === customerName);
  if (!customer) {
    const ts = now();
    customer = {
      name: customerName,
      customer_name: customerName,
      customer_type: l.company_name ? "Company" : "Individual",
      customer_group: l.company_name ? "Gewerblich" : "Privat",
      territory: l.territory ?? "Deutschland",
      email_id: l.email_id,
      mobile_no: l.mobile_no,
      disabled: 0,
      creation: ts,
      modified: ts,
    };
    store.customers.push(customer);
    store.contacts.push({
      name: `${l.lead_name}-${customerName}`,
      first_name: l.first_name,
      last_name: l.last_name,
      full_name: l.lead_name,
      email_id: l.email_id,
      mobile_no: l.mobile_no,
      company_name: customerName,
      links: [{ link_doctype: "Customer", link_name: customerName }],
      creation: ts,
      modified: ts,
    });
  }
  // Offene Chancen des Leads auf den Kunden umhängen, wie ERPNext es beim Konvertieren anbietet
  for (const o of store.opportunities) {
    if (o.opportunity_from === "Lead" && o.party_name === l.name) {
      o.opportunity_from = "Customer";
      o.party_name = customer.name;
      o.customer_name = customer.customer_name;
    }
  }
  l.status = "Converted";
  l.modified = now();
  return customer;
},

