import type { SessionUser } from "@/lib/types";

// Signiertes Session-Token: base64url(JSON) + "." + base64url(HMAC-SHA256).
// Wird sowohl im Proxy als auch serverseitig genutzt, daher nur Web Crypto.

export const SESSION_COOKIE = "crm_session";
export const SESSION_MAX_AGE = 8 * 60 * 60; // 8 Stunden

type Payload = SessionUser & { exp: number };

const DEV_SECRET = "dev-only-insecure-secret-change-me";

function secret() {
  const s = process.env.SESSION_SECRET;
  if (s && s.length >= 32) return s;
  if (process.env.NODE_ENV === "production") {
    throw new Error("SESSION_SECRET fehlt oder ist kürzer als 32 Zeichen");
  }
  return DEV_SECRET;
}

const enc = new TextEncoder();

function b64url(bytes: Uint8Array) {
  let s = "";
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function fromB64url(s: string) {
  const bin = atob(s.replace(/-/g, "+").replace(/_/g, "/"));
  return Uint8Array.from(bin, (c) => c.charCodeAt(0));
}

async function hmacKey() {
  return crypto.subtle.importKey("raw", enc.encode(secret()), { name: "HMAC", hash: "SHA-256" }, false, ["sign", "verify"]);
}

export async function signSession(user: SessionUser): Promise<string> {
  const payload: Payload = { ...user, exp: Math.floor(Date.now() / 1000) + SESSION_MAX_AGE };
  const body = b64url(enc.encode(JSON.stringify(payload)));
  const sig = new Uint8Array(await crypto.subtle.sign("HMAC", await hmacKey(), enc.encode(body)));
  return `${body}.${b64url(sig)}`;
}

export async function verifySession(token: string | undefined): Promise<SessionUser | null> {
  if (!token) return null;
  const [body, sig] = token.split(".");
  if (!body || !sig) return null;
  try {
    const ok = await crypto.subtle.verify("HMAC", await hmacKey(), fromB64url(sig), enc.encode(body));
    if (!ok) return null;
    const p = JSON.parse(new TextDecoder().decode(fromB64url(body))) as Payload;
    if (typeof p.exp !== "number" || p.exp < Date.now() / 1000) return null;
    return { user: p.user, fullName: p.fullName };
  } catch {
    return null;
  }
}

import "server-only";
import { cache } from "react";
import { cookies } from "next/headers";
import { redirect } from "next/navigation";
import { SESSION_COOKIE, verifySession } from "@/lib/session-token";

// Data Access Layer: jede Seite und jede Server Action prüft die Session selbst.
// Der Proxy leitet nur vorab um und ist nicht die einzige Schutzschicht.

export const getUser = cache(async () => {
  const token = (await cookies()).get(SESSION_COOKIE)?.value;
  return verifySession(token);
});

export async function requireUser() {
  const user = await getUser();
  if (!user) redirect("/login");
  return user;
}

import { NextResponse, type NextRequest } from "next/server";
import { SESSION_COOKIE, verifySession } from "@/lib/session-token";

// Vorab-Prüfung: ohne gültige Session → /login. Die eigentliche Prüfung
// passiert zusätzlich in Seiten, Server Actions und Route Handlern.
export default async function proxy(req: NextRequest) {
  const { pathname, search } = req.nextUrl;
  const user = await verifySession(req.cookies.get(SESSION_COOKIE)?.value);

  if (pathname === "/login") {
