import { notFound } from "next/navigation";
import { db } from "@/lib/data";
import { PageHeader } from "@/components/ui";
import { LeadEditForm } from "@/components/forms";

export const metadata = { title: "Lead bearbeiten" };

export default async function EditLeadPage({ params }: PageProps<"/leads/[name]/edit">) {
  const lead = await db().getLead(decodeURIComponent((await params).name));
  if (!lead) notFound();
  return (
    <>
      <PageHeader
        title="Bearbeiten"
        crumbs={[
          { href: "/leads", label: "Leads" },
          { href: `/leads/${encodeURIComponent(lead.name)}`, label: lead.lead_name },
        ]}
      />
      <LeadEditForm lead={lead} />
    </>
  );
}

