  const from = sp.from === "Lead" ? "Lead" : "Customer";
  const party = typeof sp.party === "string" ? sp.party : undefined;

  const [leads, customers] = await Promise.all([db().listLeads({ limit: 500 }), db().listCustomers({ limit: 500 })]);

  return (
    <>
      <PageHeader title="Neue Chance" crumbs={[{ href: "/opportunities", label: "Chancen" }]} />
      <OpportunityForm
        defaultFrom={from}
        defaultParty={party}
        leads={leads
          .filter((l) => l.status !== "Converted" && l.status !== "Do Not Contact")
          .map((l) => ({ value: l.name, label: l.company_name ? `${l.lead_name} – ${l.company_name}` : l.lead_name }))}
        customers={customers.filter((c) => !c.disabled).map((c) => ({ value: c.name, label: c.customer_name }))}
      />
    </>
  );
}

